CREATE TABLE support_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id TEXT NOT NULL,sender_id TEXT NOT NULL,sender_role TEXT NOT NULL,body TEXT NOT NULL,request_id TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(sender_id,request_id)); CREATE INDEX support_customer ON support_messages(customer_id,id); CREATE TABLE support_reads(customer_id TEXT NOT NULL,reader_id TEXT NOT NULL,last_id INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(customer_id,reader_id));
